import json
q=json.load(open('emc-fourth-cohort-quant.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            walk(v,p+'/'+str(k))
    elif isinstance(o,list):
        print(p,'[list len',len(o),']', str(o)[:300])
    else:
        print(p,'=',str(o)[:400])
walk(q)
" 2>&1 | head -80

